function createLockout({ maxFailures, lockMs }) {
  const state = new Map();
  return {
    attempt(email, passwordOk, now) {
      const key = email.trim().toLowerCase();
      const entry = state.get(key) ?? { failures: 0, lockedUntil: 0 };
      if (entry.lockedUntil > now) return "locked";
      if (passwordOk) {
        state.delete(key);
        return "ok";
      }
      entry.failures += 1;
      if (entry.failures >= maxFailures) {
        entry.failures = 0;
        entry.lockedUntil = now + lockMs;
      }
      state.set(key, entry);
      return "wrong";
    },
  };
}

const lockout = createLockout({ maxFailures: 3, lockMs: 1000 });
const attempts = [
  ["ada@example.com", false, 0], ["ADA@example.com ", false, 10], ["ada@example.com", false, 20],
  ["ada@example.com", true, 30], ["ada@example.com", true, 1030], ["ada@example.com", false, 1040],
];
console.log(attempts.map(([email, ok, now]) => lockout.attempt(email, ok, now)).join(" "));

