function createRefresher() {
  const tokens = new Map();
  let next = 1;
  const issue = (userId) => {
    const id = `t${next++}`;
    tokens.set(id, { userId, used: false });
    return id;
  };
  return {
    issue,
    refresh(tokenId) {
      const token = tokens.get(tokenId);
      if (!token) return "invalid";
      if (token.used) {
        for (const [id, other] of tokens) if (other.userId === token.userId) tokens.delete(id);
        return "replay";
      }
      token.used = true;
      return issue(token.userId);
    },
  };
}

const r = createRefresher();
const laptop = r.issue("ada");
const phone = r.issue("ada");
const next = r.refresh(laptop);
console.log(laptop, phone, next);
console.log(r.refresh(laptop), r.refresh(next), r.refresh(phone), r.refresh("t9"));

