function createResetStore() {
  const rows = new Map();
  return {
    rows,
    async issue(userId, now) {
      for (const [hash, row] of rows) if (row.userId === userId) rows.delete(hash);
      const token = crypto.randomUUID();
      rows.set(await sha256(token), { userId, expiresAt: now + 1_800_000 });
      return token;
    },
    async use(token, now) {
      const hash = await sha256(token);
      const row = rows.get(hash);
      if (!row || row.expiresAt <= now) return null;
      rows.delete(hash);
      return row.userId;
    },
  };
}

const store = createResetStore();
const first = await store.issue(4, 0);
const second = await store.issue(4, 1000);
console.log(await store.use(first, 2000), await store.use(second, 2000), await store.use(second, 3000));
const late = await store.issue(5, 0);
console.log(await store.use(late, 1_800_000), store.rows.size, [...store.rows.keys()].every((k) => k.length === 64));

