const ALLOWED = ["student", "tutor", "admin"];

function assignRoles(actor, targetId, roles) {
  if (!actor.roles.includes("admin")) return { status: 403 };
  if (actor.id === targetId) return { status: 400 };
  if (roles.length === 0 || !roles.every((role) => ALLOWED.includes(role))) return { status: 400 };
  return { status: 200, roles: [...new Set(roles)].sort() };
}

