const users = [{ email: "ada@example.com", active: true }, { email: "gone@example.com", active: false }];
const outbox = [];

function requestReset(email, users, outbox) {
  const wanted = email.trim().toLowerCase();
  const user = users.find((u) => u.email === wanted && u.active);
  if (user) outbox.push({ to: user.email });
  return { status: 202, message: "If the address has an account, a reset link is on its way." };
}

const known = requestReset(" ADA@example.com", users, outbox);
const unknown = requestReset("gone@example.com", users, outbox);
console.log(JSON.stringify(known) === JSON.stringify(unknown), known.status);
console.log(outbox);
